"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["49186"],{19694(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.etapa_nota_enem_com_banca","status":422,"titulo":"A etapa de nota do ENEM n\xe3o admite banca que avalia o m\xe9rito"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.etapa_nota_enem_com_banca","requisitos":[],"oQueAconteceu":["Uma etapa que declara a nota vinda do ENEM tamb\xe9m declara uma banca que avalia o m\xe9rito.\\nA nota dessa etapa chega pela importa\xe7\xe3o do resultado do INEP e \xe9 calculada pelo sistema;\\nningu\xe9m a atribui, e por isso n\xe3o h\xe1 banca avaliadora para ela. O recurso contra o\\nresultado \xe9 declarado na configura\xe7\xe3o do recurso da fase que publica o resultado.","A mensagem da resposta diz: \\"A etapa na posi\xe7\xe3o *n* tem a nota vinda do ENEM e n\xe3o admite\\nbanca com o papel \'Avalia o m\xe9rito\'. O recurso contra o resultado \xe9 declarado na\\nconfigura\xe7\xe3o do recurso da fase que publica o resultado.\\" A recusa sai com **422** e nada\\nfoi gravado."],"comoResolver":["Retire a banca avaliadora da etapa de nota do ENEM e reenvie as etapas\\n(`PUT /api/selecao/processos-seletivos/{id}/etapas`). Se a avalia\xe7\xe3o por banca \xe9 parte\\ndo certame, ela \xe9 outra etapa, com nota atribu\xedda pela banca, e n\xe3o a de nota do ENEM."],"ondeAparece":["- Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);